insert into public.issues (id, name, description, weight, sort_order, rubric, active) values
  ('m4a', 'Medicare for All', 'Single-payer health care. Full marks for a cosponsor or a candidate who campaigns on it by name; partial for a public option or Medicare expansion.', 1.5, 1, '{"0":"Opposes or dodges; defends private insurance status quo","1":"Vague ''universal coverage'' language only","2":"Backs a public option or Medicare buy-in","3":"Supports single payer but hedges on timeline or bill","4":"Cosponsors or campaigns on Medicare for All by name"}'::jsonb, true),
  ('gnd', 'Green New Deal / climate', 'Climate action at the scale of the Green New Deal: public investment, end fossil fuel subsidies, no new leases, a just transition.', 1, 2, '{"0":"Fossil fuel money, pro-drilling, or climate skeptic","1":"Generic ''believes in climate change''","2":"Backs IRA-style incentives, no fossil fuel phaseout","3":"Supports ending subsidies and new leasing","4":"Cosponsors or campaigns on the Green New Deal"}'::jsonb, true),
  ('labor', 'Labor and the PRO Act', 'Union rights: PRO Act, sectoral bargaining, $17+ minimum wage, walks picket lines.', 1, 3, '{"0":"Anti-union record or right-to-work support","1":"Generic pro-worker language","2":"Supports $15 minimum wage and PRO Act in principle","3":"Cosponsor of PRO Act, visible with strikes","4":"PRO Act plus sectoral bargaining, $17+ wage, union-led campaign"}'::jsonb, true),
  ('no_corp_pac', 'Rejects corporate PAC money', 'Whether the campaign takes corporate PAC, crypto super PAC, or AIPAC-aligned money.', 1.5, 4, '{"0":"Takes corporate PAC money and benefits from AIPAC/crypto super PACs","1":"Takes corporate PAC money","2":"No corporate PAC pledge, but lobbyist or super PAC support","3":"No corporate PAC pledge, small-dollar heavy","4":"No corporate PAC, no lobbyist money, disavows outside super PAC spending"}'::jsonb, true),
  ('gaza', 'Gaza ceasefire and arms conditions', 'Position on Israel''s war in Gaza: ceasefire, conditioning or blocking offensive arms, opposing AIPAC influence.', 3, 5, '{"0":"Unconditional support for arms transfers; AIPAC-backed","1":"Ceasefire language only after it became mainstream","2":"Supports ceasefire, opposes conditions on aid","3":"Supports conditioning arms and humanitarian access","4":"Voted for or campaigns on blocking offensive arms transfers; refuses AIPAC"}'::jsonb, true),
  ('housing', 'Housing', 'Social housing, rent stabilization, tenant protections, and zoning reform to build more.', 1, 6, '{"0":"Landlord-aligned, opposes tenant protections","1":"Generic ''affordability'' language","2":"Supports more building and housing vouchers","3":"Supports tenant protections and public investment","4":"Social housing, rent stabilization, and tenant right to counsel"}'::jsonb, true),
  ('tax', 'Tax the rich', 'Wealth tax, higher top rates, corporate rate increases, closing carried interest.', 1, 7, '{"0":"Supports extending Trump tax cuts","1":"Vague ''fair share'' language","2":"Repeal Trump cuts for top earners","3":"Higher corporate rate plus capital gains reform","4":"Wealth tax or billionaire minimum tax by name"}'::jsonb, true),
  ('abortion', 'Reproductive rights', 'Codify Roe, repeal Hyde, protect access to abortion medication and IVF.', 1, 8, '{"0":"Anti-abortion","1":"''Personally opposed'' or supports restrictions","2":"Supports codifying Roe","3":"Codify Roe plus repeal Hyde","4":"Full access: repeal Hyde, protect mifepristone, expand clinics with federal funding"}'::jsonb, true),
  ('immigration', 'Immigration', 'Pathway to citizenship, ending mass deportation, accountability for ICE, no border wall funding.', 2, 9, '{"0":"Supports mass deportation or the Laken Riley Act framing","1":"Border-security-first messaging","2":"Pathway to citizenship for Dreamers","3":"Broad pathway to citizenship, opposes wall funding","4":"Pathway for all, defund or abolish ICE enforcement, end detention contracts"}'::jsonb, true),
  ('justice', 'Criminal justice', 'Police accountability, ending qualified immunity, decarceration, cannabis legalization.', 1, 10, '{"0":"''Tough on crime'' platform, backs more police funding without reform","1":"Generic reform language","2":"Supports cannabis legalization and sentencing reform","3":"Ends qualified immunity, backs George Floyd Act","4":"Decarceration, ends cash bail, redirects police funding to services"}'::jsonb, true),
  ('antitrust', 'Corporate power and antitrust', 'Break up monopolies, ban stock trading in Congress, rein in Big Tech and private equity.', 1, 11, '{"0":"Deregulation agenda, tech and finance donor base","1":"Generic anti-corporate-greed language","2":"Supports congressional stock trading ban","3":"Supports antitrust enforcement, breaking up Big Tech","4":"Breakups plus private equity and crypto regulation, no industry money"}'::jsonb, true),
  ('democracy', 'Democracy reform', 'Abolish the filibuster, overturn Citizens United, expand voting rights, Supreme Court reform.', 0.75, 12, '{"0":"Opposes voting rights bills","1":"Supports voting rights bills only","2":"Supports ending the filibuster for voting rights","3":"End the filibuster, overturn Citizens United","4":"All of that plus Supreme Court term limits or expansion"}'::jsonb, true)
on conflict (id) do update set name = excluded.name, description = excluded.description, weight = excluded.weight, sort_order = excluded.sort_order, rubric = excluded.rubric, active = excluded.active;

insert into public.races (id, office, state, district, seat_id, senate_class, title, election_date, election_type, rating, incumbent_name, incumbent_party, is_open_seat, why_it_matters, notes, tracked, needs_review) values
  ('house-az-01-2026', 'house', 'AZ', 1, 'AZ-01', null, 'AZ-1 (Scottsdale, north Phoenix)', '2026-11-03', 'general', 'tossup', 'David Schweikert', 'R', true, 'Schweikert left to run for governor. Biden-Harris-competitive suburban seat that Democrats narrowly missed in 2024.', 'Shah (D) vs. Feely (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-az-06-2026', 'house', 'AZ', 6, 'AZ-06', null, 'AZ-6 (Tucson suburbs)', '2026-11-03', 'general', 'lean_r', 'Juan Ciscomani', 'R', false, 'Ciscomani has won twice by under three points.', 'Mendoza (D) vs. Ciscomani (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ca-11-2026', 'house', 'CA', 11, 'CA-11', null, 'CA-11 (San Francisco)', '2026-11-03', 'general', 'safe_d', 'Nancy Pelosi', 'D', true, 'Pelosi''s retirement set up a progressive-versus-establishment fight for one of the safest Democratic seats in the country.', 'Top two: Wiener (D) vs. Chan (D). Chakrabarti was eliminated. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ca-13-2026', 'house', 'CA', 13, 'CA-13', null, 'CA-13 (Central Valley: Merced, Modesto)', '2026-11-03', 'general', 'lean_d', 'Adam Gray', 'D', false, 'Gray won by 187 votes in 2024. Prop 50 redrew the district to be friendlier to Democrats.', 'Gray (D) vs. Kevin Lincoln (R). Lincoln finished second in the June 2 top-two primary ahead of Vin Kruttiventi.', true, false),
  ('house-ca-22-2026', 'house', 'CA', 22, 'CA-22', null, 'CA-22 (Bakersfield, Kings County)', '2026-11-03', 'general', 'tossup', 'David Valadao', 'R', false, 'Valadao voted for the Medicaid cuts in the 2025 budget bill in a district with one of the highest Medicaid shares in the country, then Prop 50 made the seat bluer.', 'Valadao (R) vs. Villegas (D), a Medicare for All progressive. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ca-45-2026', 'house', 'CA', 45, 'CA-45', null, 'CA-45 (Little Saigon, north Orange County)', '2026-11-03', 'general', 'lean_d', 'Derek Tran', 'D', false, 'Tran flipped this seat by 653 votes in 2024.', 'Tran (D) vs. Vo (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-co-08-2026', 'house', 'CO', 8, 'CO-08', null, 'CO-8 (Adams and Weld counties)', '2026-11-03', 'general', 'tossup', 'Gabe Evans', 'R', false, 'The most evenly divided district in Colorado. Evans won by under a point in 2024.', 'Rutinel (D) vs. Evans (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ga-13-2026', 'house', 'GA', 13, 'GA-13', null, 'GA-13 (south metro Atlanta)', '2026-11-03', 'general', 'safe_d', 'Everton Blair', 'D', true, 'Scott, 80, drew a crowded primary from younger challengers, then died in April. A generational-change test in a safe seat.', 'Jasmine Clark (D) vs. Jonathan Chavez (R). David Scott died April 22, 2026 while seeking a 13th term; Clark won the May 19 primary outright with 56%. Everton Blair won the separate special election for the rest of Scott''s term.', true, false),
  ('house-ia-01-2026', 'house', 'IA', 1, 'IA-01', null, 'IA-1 (southeast Iowa, Davenport)', '2026-11-03', 'general', 'tossup', 'Mariannette Miller-Meeks', 'R', false, 'Miller-Meeks survived by 799 votes in 2024. Bohannan is back for a third try.', 'Bohannan (D) vs. Miller-Meeks (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-il-07-2026', 'house', 'IL', 7, 'IL-07', null, 'IL-7 (Chicago West Side, downtown)', '2026-11-03', 'general', 'safe_d', 'Danny Davis', 'D', true, 'Davis retired after 15 terms. Kina Collins, who came within four points of him in 2022, ran again in a crowded field.', 'La Shawn Ford (D) vs. Koppie (R). Kina Collins lost the primary. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-il-09-2026', 'house', 'IL', 9, 'IL-09', null, 'IL-9 (Chicago North Side, Evanston)', '2026-11-03', 'general', 'safe_d', 'Jan Schakowsky', 'D', true, 'Schakowsky''s retirement opened a deep-blue seat. Kat Abughazaleh''s small-dollar campaign against a field of state legislators drew national attention.', 'Biss (D) vs. Elleson (R). Abughazaleh lost the primary. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-me-02-2026', 'house', 'ME', 2, 'ME-02', null, 'ME-2 (northern Maine)', '2026-11-03', 'general', 'lean_r', 'Jared Golden', 'D', true, 'Golden retired from a Trump +9 district. Former governor Paul LePage is the Republican nominee.', 'Dunlap (D) vs. LePage (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-mi-07-2026', 'house', 'MI', 7, 'MI-07', null, 'MI-7 (Lansing)', '2026-11-03', 'general', 'tossup', 'Tom Barrett', 'R', false, 'Open in 2024 when Slotkin left for the Senate; Barrett won by under four points.', 'Lawrence (D) vs. Barrett (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-mi-10-2026', 'house', 'MI', 10, 'MI-10', null, 'MI-10 (Macomb County)', '2026-11-03', 'general', 'tossup', 'John James', 'R', true, 'James left to run for governor. Democrats came within half a point here in 2022.', 'Hines (D) vs. Bouchard (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-mi-13-2026', 'house', 'MI', 13, 'MI-13', null, 'MI-13 (Detroit)', '2026-11-03', 'general', 'safe_d', 'Shri Thanedar', 'D', false, 'Justice Democrats backed state Rep. Donavan McKinney against self-funding incumbent Thanedar. The marquee progressive primary challenge of the cycle.', 'McKinney (D) beat Thanedar 51.9% to 48.1% on Aug 4. Republican primary was Articia Bomer vs. Andrew Lorenz; the winner is not yet recorded here. Independent Maurice Morton is also on the general ballot.', true, true),
  ('house-ne-02-2026', 'house', 'NE', 2, 'NE-02', null, 'NE-2 (Omaha)', '2026-11-03', 'general', 'tossup', 'Don Bacon', 'R', true, 'Bacon retired from a Harris-won district. Best Democratic pickup chance in the Plains.', 'Denise Powell (D) vs. Harding (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-nj-07-2026', 'house', 'NJ', 7, 'NJ-07', null, 'NJ-7 (Hunterdon, Warren, western Union)', '2026-11-03', 'general', 'tossup', 'Tom Kean Jr.', 'R', false, 'Kean underperformed Trump in 2024 and Sherrill carried the district in the 2025 governor''s race.', 'Bennett (D) vs. Kean (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ny-07-2026', 'house', 'NY', 7, 'NY-07', null, 'NY-7 (Brooklyn, Queens)', '2026-11-03', 'general', 'safe_d', 'Nydia Velázquez', 'D', true, 'Velázquez retired from the most DSA-friendly district in the country. Claire Valdez ran with NYC-DSA backing against establishment-aligned Democrats.', 'Claire Valdez (D) vs. Rivera (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ny-10-2026', 'house', 'NY', 10, 'NY-10', null, 'NY-10 (Lower Manhattan, brownstone Brooklyn)', '2026-11-03', 'general', 'safe_d', 'Dan Goldman', 'D', false, 'Former NYC comptroller Brad Lander challenged Goldman from the left in the highest-profile House primary in the city.', 'Lander (D) vs. Moore (R). Goldman lost. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ny-12-2026', 'house', 'NY', 12, 'NY-12', null, 'NY-12 (Manhattan: Upper East and West Sides)', '2026-11-03', 'general', 'safe_d', 'Jerry Nadler', 'D', true, 'Nadler''s retirement produced a large field including Assemblymembers Micah Lasher and Alex Bores and Jack Schlossberg.', 'Lasher (D) vs. Shinkle (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ny-17-2026', 'house', 'NY', 17, 'NY-17', null, 'NY-17 (Hudson Valley: Rockland, Putnam, north Westchester)', '2026-11-03', 'general', 'tossup', 'Mike Lawler', 'R', false, 'Harris carried the district. Lawler is the top Democratic target in New York.', 'Cait Conley (D) vs. Lawler (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-nc-01-2026', 'house', 'NC', 1, 'NC-01', null, 'NC-1 (northeast North Carolina)', '2026-11-03', 'general', 'lean_r', 'Don Davis', 'D', false, 'The legislature redrew NC-1 in October 2025 specifically to unseat Davis.', 'Davis (D) vs. Buckhout (R) in the redrawn district. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-oh-09-2026', 'house', 'OH', 9, 'OH-09', null, 'OH-9 (Toledo)', '2026-11-03', 'general', 'tossup', 'Marcy Kaptur', 'D', false, 'Kaptur, the longest-serving woman in Congress, holds a Trump district under a new 2026 map.', 'Kaptur (D) vs. Merrin (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-oh-13-2026', 'house', 'OH', 13, 'OH-13', null, 'OH-13 (Akron)', '2026-11-03', 'general', 'tossup', 'Emilia Sykes', 'D', false, 'Sykes won by two points in 2024 and the 2026 map shifted the district slightly right.', 'Sykes (D) vs. Coleman (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-pa-01-2026', 'house', 'PA', 1, 'PA-01', null, 'PA-1 (Bucks County)', '2026-11-03', 'general', 'lean_r', 'Brian Fitzpatrick', 'R', false, 'Harris carried the district but Fitzpatrick''s crossover appeal has held for four cycles.', 'Harvie (D) vs. Fitzpatrick (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-pa-03-2026', 'house', 'PA', 3, 'PA-03', null, 'PA-3 (Philadelphia)', '2026-11-03', 'general', 'safe_d', 'Dwight Evans', 'D', true, 'Evans retired. State Sen. Sharif Street and state Rep. Chris Rabb, a Working Families-aligned progressive, led the field.', 'Chris Rabb (D) is unopposed in the general; no Republican filed in PA-3. Rabb beat Sharif Street, Ala Stanford, and Shaun Griffith on May 19 by about 15 points.', true, false),
  ('house-pa-07-2026', 'house', 'PA', 7, 'PA-07', null, 'PA-7 (Lehigh Valley)', '2026-11-03', 'general', 'tossup', 'Ryan Mackenzie', 'R', false, 'Mackenzie ousted Susan Wild by one point in 2024.', 'Bob Brooks (D) vs. Mackenzie (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-pa-08-2026', 'house', 'PA', 8, 'PA-08', null, 'PA-8 (Scranton, Wilkes-Barre)', '2026-11-03', 'general', 'tossup', 'Rob Bresnahan', 'R', false, 'Bresnahan beat Matt Cartwright by under two points and has drawn stock-trading scrutiny.', 'Cognetti (D) vs. Bresnahan (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-tx-18-2026', 'house', 'TX', 18, 'TX-18', null, 'TX-18 (Houston)', '2026-11-03', 'general', 'safe_d', 'Christian Menefee', 'D', false, 'Menefee won the January 2026 special. Al Green, drawn out of TX-9 by the 2025 map, challenged him for the full term.', 'Menefee (D) vs. Whitfield (R). Green lost the runoff. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-tx-28-2026', 'house', 'TX', 28, 'TX-28', null, 'TX-28 (Laredo, south Texas)', '2026-11-03', 'general', 'tossup', 'Henry Cuellar', 'D', false, 'Cuellar, under federal indictment and one of the most conservative House Democrats, is running in a redrawn seat.', 'Cuellar (D) vs. Tijerina (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-tx-34-2026', 'house', 'TX', 34, 'TX-34', null, 'TX-34 (Rio Grande Valley)', '2026-11-03', 'general', 'tossup', 'Vicente Gonzalez', 'D', false, 'The 2025 map made this Valley seat significantly redder.', 'Gonzalez (D) vs. Eric Flores (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-tx-37-2026', 'house', 'TX', 37, 'TX-37', null, 'TX-37 (Austin)', '2026-11-03', 'general', 'safe_d', 'Lloyd Doggett', 'D', true, 'Doggett stepped aside after the 2025 map carved up Greg Casar''s TX-35. Casar, chair of the Progressive Caucus, is running here.', 'Casar (D) vs. Peña (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-ut-01-2026', 'house', 'UT', 1, 'UT-01', null, 'UT-1 (Salt Lake County, court-ordered map)', '2026-11-03', 'general', 'lean_d', 'Blake Moore', 'R', true, 'A state court ordered a map with a Democratic-leaning Salt Lake City seat for 2026, the first realistic Democratic House seat in Utah in a decade.', 'McAdams (D) vs. Owen (R). Blake Moore moved to the 2nd district. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('house-wi-03-2026', 'house', 'WI', 3, 'WI-03', null, 'WI-3 (western Wisconsin, La Crosse, Eau Claire)', '2026-11-03', 'general', 'tossup', 'Derrick Van Orden', 'R', false, 'Rebecca Cooke came within three points in 2024 and is running again.', 'Cooke (D) vs. Van Orden (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('senate-tx-2026', 'senate', 'TX', null, null, 2, 'Texas Senate', '2026-11-03', 'general', 'lean_r', 'John Cornyn', 'R', true, 'A Cornyn-Paxton Republican runoff and a Talarico-Crockett Democratic primary made this the most expensive Senate race in the country.', 'Talarico (D) vs. Paxton (R). Cornyn lost the runoff. Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('senate-mi-2026', 'senate', 'MI', null, null, 2, 'Michigan Senate', '2026-11-03', 'general', 'tossup', 'Gary Peters', 'D', true, 'Abdul El-Sayed ran an explicitly progressive campaign against Rep. Haley Stevens and state Sen. Mallory McMorrow. The Republican is Mike Rogers.', 'El-Sayed (D) vs. Rogers (R). McMorrow suspended her campaign July 5, leaving a two-way primary.', true, false),
  ('senate-mn-2026', 'senate', 'MN', null, null, 2, 'Minnesota Senate', '2026-11-03', 'general', 'likely_d', 'Tina Smith', 'D', true, 'Lt. Gov. Peggy Flanagan (progressive) vs. Rep. Angie Craig (moderate) for an open seat.', 'Flanagan (D) vs. Tafoya (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
  ('senate-me-2026', 'senate', 'ME', null, null, 2, 'Maine Senate', '2026-11-03', 'general', 'tossup', 'Susan Collins', 'R', false, 'Oysterman and veteran Graham Platner''s insurgent campaign against Gov. Janet Mills for the right to face Collins.', 'Troy Jackson (D, chosen at the July state convention after Platner withdrew July 5-10) vs. Collins (R).', true, true),
  ('senate-nc-2026', 'senate', 'NC', null, null, 2, 'North Carolina Senate', '2026-11-03', 'general', 'tossup', 'Thom Tillis', 'R', true, 'Former governor Roy Cooper against former RNC chair Michael Whatley. The Democrats'' best pickup opportunity.', 'Cooper (D) vs. Whatley (R). Per Wikipedia, checked Sept 2, 2026.', true, true),
