  ('gov-fl-donalds', 'gov-fl-2026', 'Byron Donalds', 'R', false, 'won_primary', null, 'Congressman, FL-19; Trump-endorsed.', null, 0.636, null, null, null, null, null, null, null, 2, false),
  ('gov-ia-sand', 'gov-ia-2026', 'Rob Sand', 'D', false, 'won_primary', null, 'State auditor; moderate, pro-gun-rights Democrat with record fundraising.', null, null, null, 'Only Democrat to file. Endorsed by the Iowa Federation of Labor AFL-CIO, UAW, ISEA and End Citizens United. Campaigns explicitly on winning Republican and independent voters and on standing up to his own party.', 'No published position found on: Labor and the PRO Act, Gaza ceasefire and arms conditions, Housing, Tax the rich, Democracy reform,', null, null, null, null, 1, false),
  ('gov-ia-feenstra', 'gov-ia-2026', 'Randy Feenstra', 'R', false, 'lost_primary', null, 'Congressman, IA-4.', null, 0.467, null, null, null, null, null, null, null, 2, false),
  ('gov-ia-lahn', 'gov-ia-2026', 'Zach Lahn', 'R', false, 'won_primary', null, 'Won the Republican nomination over Randy Feenstra and others.', null, null, null, null, null, null, null, null, null, 3, false),
  ('gov-nv-ford', 'gov-nv-2026', 'Aaron Ford', 'D', false, 'won_primary', 'https://www.fordfornevada.com/', 'State attorney general.', null, null, null, 'Confirmed in August 2026 that he will not raise taxes at all as governor. The rubric has no level for a Democrat ruling out revenue increases; coded 1 on the fair-share language in the rest of his record, which may understate the distance from your scale.', 'No published position found on: Gaza ceasefire and arms conditions, Reproductive rights, Corporate power and antitrust, Democracy reform,', null, null, null, null, 1, true),
  ('gov-nv-lombardo', 'gov-nv-2026', 'Joe Lombardo', 'R', true, 'won_primary', null, null, null, null, null, null, null, null, null, null, null, 2, false),
  ('gov-me-pingree', 'gov-me-2026', 'Hannah Pingree', 'D', false, 'won_primary', 'https://hannahforgovernor.com/', 'Former state House speaker; daughter of Rep. Chellie Pingree.', null, null, null, 'Won the June 9 ranked-choice primary over Bellows, Jackson, and King. Co-chaired the Maine Climate Council and led the Maine Won''t Wait climate plan; endorsed by Maine Conservation Voters. Pledged tribal sovereignty legislation in her first 100 days.', 'No published position found on: Rejects corporate PAC money, Gaza ceasefire and arms conditions, Criminal justice, Corporate power and antitrust, Democracy reform,', null, null, null, null, 2, false),
  ('gov-me-bellows', 'gov-me-2026', 'Shenna Bellows', 'D', false, 'lost_primary', 'https://www.bellowsformaine.com/', 'Secretary of state; former ACLU of Maine director.', null, null, null, null, null, null, null, null, null, 3, false),
  ('gov-me-king', 'gov-me-2026', 'Angus King III', 'D', false, 'lost_primary', 'https://angusforgovernor.com/', 'Clean-energy executive; son of Sen. Angus King.', null, -0.17, null, null, null, null, null, null, null, 4, false),
  ('gov-me-charles', 'gov-me-2026', 'Robert Charles', 'R', false, 'won_primary', null, 'Former assistant secretary of state; won the Republican primary.', null, null, null, null, null, null, null, null, null, 5, false),
  ('gov-me-bennett', 'gov-me-2026', 'Rick Bennett', 'I', false, 'running', 'https://bennettforgovernor.com/', 'State senator who left the Republican Party; running as an independent.', null, null, null, 'Not yet coded: independent candidate with an executive or state-legislative record rather than a federal platform. Former Maine GOP chair, Senate president and 2016 Trump elector who left the party in 2025. Maine Newsroom documents a record of supporting cuts to Social Security and MaineCare. Website added.', 'No published position found on: Green New Deal / climate, Labor and the PRO Act, Rejects corporate PAC money, Gaza ceasefire and arms conditions, Immigration, Criminal justice, Corporate power and antitrust, Democracy reform,', null, null, null, null, 6, true),
  ('gov-mn-klobuchar', 'gov-mn-2026', 'Amy Klobuchar', 'D', false, 'won_primary', null, 'U.S. senator since 2007; entered after Walz withdrew.', null, -0.278, null, null, 'No published position found on: Green New Deal / climate, Immigration, Criminal justice,', null, null, null, null, 1, false),
  ('gov-mn-demuth', 'gov-mn-2026', 'Lisa Demuth', 'R', false, 'won_primary', null, 'State House speaker.', null, null, null, null, null, null, null, null, null, 2, false)
on conflict (id) do update set race_id = excluded.race_id, name = excluded.name, party = excluded.party, is_incumbent = excluded.is_incumbent, status = excluded.status, website = excluded.website, bio = excluded.bio, fec_id = excluded.fec_id, dw_nominate = excluded.dw_nominate, photo_url = excluded.photo_url, notes = excluded.notes, open_questions = excluded.open_questions, nonindividual_share = excluded.nonindividual_share, outside_spending_for = excluded.outside_spending_for, outside_spending_against = excluded.outside_spending_against, top_outside_spenders = excluded.top_outside_spenders, sort_order = excluded.sort_order, needs_review = excluded.needs_review;

insert into public.scores (candidate_id, issue_id, score, evidence, source_url, provisional) values
  ('az01-galan-woods', 'no_corp_pac', 1, 'Accepts PAC money.', null, true),
  ('az01-shah', 'm4a', 3, 'Has publicly endorsed universal single-payer health care and Medicare for All and calls health care a right, while as a practicing physician discussing tradeoffs between systems; his campaign messaging leads on protecting Medicare and Medicaid and expanding coverage. Raised 2 to 3: supports single payer but hedges on timeline and mechanism.', 'https://www.predictionedge.com/elections/profile/amish-shah/', true),
  ('az01-shah', 'no_corp_pac', 2, 'FEC: his committee reports $1.83M in receipts, 8.0% from other political committees. Outside spending in his race ran heavily against him, $1.75M from Bold America and $891K from Pro-Choice Majority Action, with $196K supporting him from Physician Voices United.', 'https://www.fec.gov/data/independent-expenditures/', false),
  ('az01-cherny', 'no_corp_pac', 1, 'Accepts PAC money.', null, true),
  ('az06-mendoza', 'immigration', 2, 'Campaign bio: daughter of farmworkers; supports protecting Dreamers and a path to citizenship for those who follow the rules. Dreamer-focused pathway.', 'https://www.joannamendoza.com/', true),
  ('az06-mendoza', 'm4a', 2, 'Campaign: protect the VA, expand access to affordable care, lower drug costs; no single-payer position. Public option framing.', 'https://www.joannamendoza.com/', true),
  ('az06-mendoza', 'no_corp_pac', 3, 'Campaign pledges not to accept corporate PAC money. FEC: 7.0% of receipts from other political committees (includes ActBlue conduit).', 'https://api.open.fec.gov', true),
  ('ca11-chakrabarti', 'gaza', 4, 'Calls for ending offensive arms transfers to Israel.', null, true),
  ('ca11-chakrabarti', 'gnd', 4, 'Helped draft the original Green New Deal resolution as AOC''s chief of staff.', null, true),
  ('ca11-chakrabarti', 'housing', 3, 'Public investment and social housing planks.', null, true),
  ('ca11-chakrabarti', 'm4a', 4, 'Campaign platform: Medicare for All.', null, true),
  ('ca11-chakrabarti', 'no_corp_pac', 3, 'No corporate PAC money; largely self-funded from tech wealth.', null, true),
  ('ca11-chakrabarti', 'tax', 4, 'Backs a wealth tax.', null, true),
  ('ca11-wiener', 'abortion', 4, 'Authored SB 107 (2022) making California a sanctuary for transgender and abortion care and multiple abortion-access bills. State codification and protection record; federal Hyde repeal is outside his office.', 'https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202120220SB107', true),
  ('ca11-wiener', 'gaza', 3, 'Supported a ceasefire from November 2023, said on January 11, 2026 that Israel’s conduct in Gaza "qualifies as genocide," and per Jewish Insider supports the Block the Bombs Act, which conditions weapons transfers to Israel while exempting defensive systems. Raised from 1 to 3: supports conditioning arms. Not 4 because his support for the bill is reported rather than on his own site and he has not pledged an arms embargo or rejected pro-Israel support.', 'https://jewishinsider.com/2026/07/connie-chan-track-aipac-endorsement-scott-wiener-pelosi-schiff/', true),
  ('ca11-wiener', 'gnd', 3, 'Authored SB 253, the Climate Corporate Data Accountability Act, requiring large companies to disclose emissions, and championed the 2022 climate package. Emissions regulation and clean energy; no fossil fuel phaseout by name.', 'https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202320240SB253', true),
  ('ca11-wiener', 'housing', 3, 'Authored SB 35 (2017) streamlining approvals and SB 79 (2025) upzoning near transit; national YIMBY leader. Strong on supply; weaker on tenant protections, and no rent stabilization or right to counsel commitment.', 'https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202520260SB79', true),
  ('ca11-wiener', 'm4a', 3, 'Authored SB 562, the Healthy California Act, a state single-payer bill, in 2017; has since emphasised ACA defence and drug pricing. Single-payer record without a current Medicare for All commitment.', 'https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=201720180SB562', true),
  ('ca11-wiener', 'no_corp_pac', 1, 'Accepts corporate and real estate PAC money; Elect Democratic Women PAC network, which has received AIPAC funding, has spent in the race. No pledge.', 'https://www.fec.gov/data/', true),
  ('ca13-gray', 'gnd', 1, 'Assembly record backed by agriculture and oil interests, including votes against cap-and-trade extensions opposed by the Western States Petroleum Association; in the 119th Congress cosponsors no climate legislation. Below IRA-style incentives.', 'https://www.congress.gov/member/adam-gray/G000605', true),
  ('ca13-gray', 'immigration', 1, 'Voted for the Laken Riley Act (S.5) on January 22, 2025, Roll no. 23. Enforcement-first.', 'https://clerk.house.gov/Votes/202523', false),
  ('ca13-gray', 'm4a', 1, 'Blue Dog Coalition member who opposes single payer; backs ACA subsidies. Incremental only.', 'https://www.congress.gov/member/adam-gray/G000605', true),
  ('ca13-gray', 'no_corp_pac', 1, 'Accepts corporate PAC money; no pledge. FEC: 30.2% of receipts from other political committees (includes ActBlue conduit).', 'https://api.open.fec.gov', true),
  ('ca22-bains', 'gnd', 1, 'Voted with oil interests on several Assembly climate bills.', null, true),
  ('ca22-bains', 'm4a', 2, 'Physician; backs expanding Medi-Cal and a public option rather than single payer.', null, true),
  ('ca22-bains', 'no_corp_pac', 1, 'Accepts PAC money; has drawn oil-industry support in the Assembly.', null, true),
  ('ca22-villegas', 'labor', 3, 'Cost of living page: notes the minimum wage would be $25 an hour had it tracked productivity and calls for raising it, alongside universal childcare and paid family leave; housing and jobs pages commit to union jobs and a just transition for energy workers. The $17+ wage element of level 4 is met, but the PRO Act and sectoral bargaining are not named anywhere on the site.', 'https://www.villegasforcongress.com/issues/healthcare', true),
  ('ca22-villegas', 'm4a', 4, 'Healthcare page: "I believe healthcare is a human right, and am a strong supporter of Medicare for All," plus price caps on procedures and drugs and a commitment that any Medicare for All bill he signs will include dental and vision. Named directly.', 'https://www.villegasforcongress.com/issues/immigration', false),
  ('ca22-villegas', 'no_corp_pac', 3, 'Fight Political Corruption page: ban corporate PACs from buying influence and end Citizens United; cost of living page names PG&E, UnitedHealth and BlackRock contributions as buying politicians’ silence. Refuses corporate PAC money. No explicit disavowal of outside super PAC spending, so not 4.', 'https://www.villegasforcongress.com/issues/fight-political-corruption', false),
  ('ca45-tran', 'labor', 3, 'Original cosponsor of H.R.20, the Richard L. Trumka PRO Act of 2025 (2025-03-05).', 'https://www.congress.gov/bill/119th-congress/house-bill/20/cosponsors', false),
  ('ca45-tran', 'm4a', 2, 'Supports a public option and ACA subsidies; not single payer. Cosponsors Medicare dental and drug pricing bills.', 'https://www.congress.gov/member/derek-tran/T000491', true),
  ('ca45-tran', 'no_corp_pac', 2, 'Does not accept corporate PAC money per his campaign; $5.8M in outside spending supported him.', 'https://www.derektran.com/', true),
  ('co08-rutinel', 'gnd', 3, 'Environmental attorney and climate-focused state legislator; campaigns on clean energy and cutting utility costs. Clean energy plus a legislative record; no fossil phaseout by name, and he moved toward supporting fracking during the primary.', 'https://www.manny4colorado.com/', true),
  ('co08-rutinel', 'm4a', 2, 'Supports a public option; walked back Medicare for All during the primary. Public option.', 'https://www.manny4colorado.com/', true),
  ('co08-rutinel', 'no_corp_pac', 3, 'No corporate PAC pledge. $1.5M in outside spending supported him.', 'https://www.manny4colorado.com/', true),
  ('co08-bird', 'no_corp_pac', 1, 'Accepts PAC money.', null, true),
  ('ga13-scott', 'antitrust', 1, 'Agribusiness-aligned on the Agriculture Committee.', null, true),
  ('ga13-scott', 'no_corp_pac', 0, 'Heavy agribusiness and corporate PAC funding.', null, true),
  ('ga13-blair', 'no_corp_pac', 3, 'No corporate PAC pledge.', null, true),
  ('ga13-clark', 'm4a', 3, 'iVoterGuide survey for her state House race: selected the option that health care for all should be guaranteed and funded by the government with no private option, the survey''s Medicare for All choice. Her congressional platform emphasises protecting health care without naming the bill, so 3 rather than 4.', 'https://ivoterguide.com/candidate/46820/race/20079/election/1226', true),
  ('ga13-clark', 'no_corp_pac', 3, 'Campaign pledges no corporate PAC money; Fairshake affiliate Protect Progress spent $8.45M for her without solicitation. FEC: 3.4% of receipts from other political committees (includes ActBlue conduit).', 'https://api.open.fec.gov', true),
  ('ia01-bohannan', 'abortion', 3, 'Central to her 2024 campaign after Iowa''s six-week ban took effect; pledges to restore Roe protections federally. Codify Roe plus a restoration commitment; Hyde repeal not named.', 'https://www.christinaforiowa.com/', true),
  ('ia01-bohannan', 'antitrust', 3, 'Campaigns on banning congressional stock trading and anti-corruption reform; as a law professor and legislator focused on corporate accountability. Stock ban plus anti-corruption; breakups not named.', 'https://www.christinaforiowa.com/', true),
  ('ia01-bohannan', 'm4a', 2, 'Supports a public option and lowering drug costs; not single payer.', 'https://www.christinaforiowa.com/', true),
  ('ia01-bohannan', 'no_corp_pac', 3, 'No corporate PAC pledge maintained across her 2022, 2024 and 2026 runs. $1.3M in outside spending supported her.', 'https://www.christinaforiowa.com/', true),
  ('il07-collins', 'gaza', 4, 'Early ceasefire call; supports conditioning arms.', null, true),
  ('il07-collins', 'gnd', 4, 'Green New Deal supporter; Sunrise-aligned.', null, true),
  ('il07-collins', 'justice', 4, 'Gun violence prevention organizer; backs ending cash bail and qualified immunity.', null, true),
  ('il07-collins', 'm4a', 4, 'Signature issue across three campaigns.', null, true),
  ('il07-collins', 'no_corp_pac', 4, 'No corporate PAC, no lobbyist money pledge.', null, true),
  ('il07-ford', 'justice', 3, 'Sponsored Illinois cannabis legalization and expungement provisions and chaired the House Restorative Justice Committee. Cannabis plus sentencing and re-entry reform; qualified immunity not named.', 'https://en.wikipedia.org/wiki/La_Shawn_Ford', true),
  ('il07-ford', 'm4a', 2, 'WTTW questionnaire: protect and strengthen the ACA and expand coverage; not a single-payer champion. Public option framing.', 'https://news.wttw.com/elections/voters-guide/2026-primary/lashawn-k-ford', true),
  ('il07-conyears-ervin', 'm4a', 1, 'No stated single-payer position.', null, true),
  ('il07-conyears-ervin', 'no_corp_pac', 1, 'Accepts PAC and machine-aligned money.', null, true),
  ('il09-abughazaleh', 'gaza', 4, 'Palestinian-American; calls for an arms embargo.', null, true),
  ('il09-abughazaleh', 'gnd', 4, 'Green New Deal supporter.', null, true),
  ('il09-abughazaleh', 'housing', 3, 'Backs rent stabilization and social housing.', null, true),
  ('il09-abughazaleh', 'immigration', 4, 'Arrested protesting at Broadview ICE facility in 2025; calls to abolish ICE.', null, true),
  ('il09-abughazaleh', 'm4a', 4, 'Medicare for All is a core plank.', null, true),
  ('il09-abughazaleh', 'no_corp_pac', 4, 'No corporate PAC, no lobbyist money; small-dollar campaign.', null, true),
  ('il09-biss', 'gaza', 4, 'Evanston RoundTable questionnaire, in his own words: "The U.S. must enact the Block the Bombs Act, formally recognize a Palestinian state, and increase humanitarian aid to Gaza." Supports an offensive weapons ban on Israel and was targeted by AIPAC in the primary. Raised from 2: campaigns on blocking offensive arms transfers and refuses AIPAC.', 'https://evanstonroundtable.com/govpack_profiles/daniel-biss/', false),
  ('il09-biss', 'gnd', 3, 'As Evanston mayor advanced a climate action and resilience plan and building electrification; WTTW questionnaire supports clean energy and the Green New Deal per his Jim Owles-style answers. Strong local record; no federal fossil phaseout by name retrieved.', 'https://news.wttw.com/elections/voters-guide/2026-primary/daniel-biss', true),
  ('il09-biss', 'm4a', 4, 'WTTW voter guide: "Congress needs to pass Medicare for All and deliver the affordable health care people enjoy in nearly every other advanced democracy." Raised from 3: named directly.', 'https://news.wttw.com/elections/voters-guide/2026-primary/daniel-biss', false),
  ('il09-biss', 'no_corp_pac', 3, 'Refuses corporate PAC money; AIPAC-aligned money targeted him. FEC: 7.0% of receipts from other political committees (includes ActBlue conduit).', 'https://api.open.fec.gov', true),
  ('il09-biss', 'tax', 4, 'WTTW voter guide: "I support modest wealth tax on the assets of billionaires and ultra-millionaires," plus rolling back the Trump cuts for the ultra-wealthy, closing carried interest loopholes and taxing capital gains as wages above \$1 million. Raised from 3: wealth tax by name.', 'https://news.wttw.com/elections/voters-guide/2026-primary/daniel-biss', false),
  ('il09-fine', 'm4a', 2, 'Public option language only.', null, true),
  ('il09-fine', 'no_corp_pac', 1, 'Accepts PAC money.', null, true),
  ('me02-wood', 'antitrust', 3, 'Backs a congressional stock trading ban and antitrust enforcement (End Citizens United alum).', null, true),
  ('me02-wood', 'democracy', 3, 'Campaign built around overturning Citizens United.', null, true),
  ('me02-wood', 'm4a', 2, 'Public option; district-tailored messaging.', null, true),
  ('me02-wood', 'no_corp_pac', 4, 'Anti-corruption platform; no corporate PAC or lobbyist money.', null, true),
  ('mi07-brink', 'democracy', 3, 'Resigned as ambassador over Trump''s Ukraine policy; rule-of-law focus.', null, true),
  ('mi07-brink', 'm4a', 1, 'No single-payer position; lowering costs messaging.', null, true),
  ('mi07-brink', 'no_corp_pac', 2, 'No corporate PAC pledge; establishment-recruited.', null, true),
  ('mi10-hines', 'justice', 2, 'Former prosecutor who campaigns on sentencing reform and diversion; Macomb Defenders questionnaire lists justice reform among priorities. Sentencing reform; no qualified immunity or bail position.', 'https://macombdefenders.com/voters-guide/', true),
  ('mi10-hines', 'no_corp_pac', 2, 'Campaign pledges no corporate PAC money. FEC: 6.3% of receipts from other political committees (includes ActBlue conduit).', 'https://api.open.fec.gov', true),
  ('mi13-thanedar', 'democracy', 2, 'Filed Trump impeachment articles in 2025, then withdrew them under pressure.', null, true),
  ('mi13-thanedar', 'gaza', 1, 'Voted against conditioning arms; quit the Progressive Caucus over Israel in 2023.', null, true),
  ('mi13-thanedar', 'labor', 3, 'Original cosponsor of H.R.20, the Richard L. Trumka PRO Act of 2025 (2025-03-05).', 'https://www.congress.gov/bill/119th-congress/house-bill/20/cosponsors', false),
  ('mi13-thanedar', 'm4a', 4, 'Original cosponsor of H.R.3069, the Medicare for All Act (2025-04-29).', 'https://www.congress.gov/bill/119th-congress/house-bill/3069/cosponsors', false),
  ('mi13-thanedar', 'no_corp_pac', 2, 'Self-funds; has accepted some PAC money.', null, true),
  ('mi13-mckinney', 'gaza', 4, 'Bridge Detroit: ran on "ending military aid and arms to Israel"; Democracy Now: platform of ending military aid to Israel; backed by PAL PAC and Tlaib. Total arms and aid cutoff; refuses AIPAC-aligned money.', 'https://www.bridgedetroit.com/mckinney-ousts-thanedar-vows-to-deliver-for-working-people/', false),
  ('mi13-mckinney', 'gnd', 4, 'Bridge Detroit: platform of greater environmental protections through a Green New Deal; opposes data center mega-sites without an environmental justice plan; legislative record on utility monopoly accountability. Green New Deal by name.', 'https://www.bridgedetroit.com/mckinney-ousts-thanedar-vows-to-deliver-for-working-people/', false),
  ('mi13-mckinney', 'housing', 4, 'Priorities page, his own words: "I support a national homes guarantee that would give every Michigander safe, sustainable, and permanently affordable housing." Raised from 3 to 4: a national homes guarantee is social housing at scale.', 'https://www.donavanforcongress.com/priorities', false),
  ('mi13-mckinney', 'labor', 4, 'Former political director of SEIU Healthcare Michigan; campaign backed by SEIU and other unions; legislative focus on expanding union and worker rights. Union-led campaign; PRO Act not named in retrieved material.', 'https://www.democracynow.org/2026/8/14/donavan_mckinney', true),
  ('mi13-mckinney', 'm4a', 4, 'Priorities page, his own words: "our families cannot afford anything less than Medicare for All," including dental, vision, mental health, reproductive and abortion care and long-term supports. Named directly.', 'https://www.donavanforcongress.com/priorities', false),
  ('mi13-mckinney', 'no_corp_pac', 4, 'Democracy Now: "McKinney took no corporate PAC money"; platform centred on getting corporate money out of politics and campaign finance reform. Crypto super PAC Protect Progress spent $269K against him.', 'https://www.democracynow.org/2026/8/14/donavan_mckinney', false),
  ('ne02-cavanaugh', 'm4a', 2, 'Public option.', null, true),
  ('ne02-cavanaugh', 'no_corp_pac', 2, 'No corporate PAC pledge.', null, true),
  ('ne02-powell', 'abortion', 3, 'Reproductive rights organizer who co-founded Women Who Run after the Dobbs decision; endorsed by EMILY''s List; Pro-Choice Majority 2026 spent $242K for her. Codify Roe with an organizing record; Hyde repeal not named.', 'https://www.denisepowellforcongress.com/', true),
  ('ne02-powell', 'no_corp_pac', 2, 'FEC Schedule E: $6.14 million in independent expenditures supported her, led by Fight for Nebraska PAC at $2.72M, CHC BOLD PAC at $1.11M and Bold America at $838K. Bold America received $1.55 million from AIPAC’s United Democracy Project in the 2026 cycle. Her own committee reports $2.67M in receipts, 11.6% from other political committees. Her no-AIPAC-money pledge covers direct contributions; outside spending on her behalf is partly AIPAC-funded. Level 2: a pledge alongside substantial super PAC support.', 'https://www.fec.gov/data/independent-expenditures/', false),
  ('nj07-bennett', 'm4a', 1, 'Campaign: lower health care costs and protect the ACA; no public option or single payer position.', 'https://rebeccabennettforcongress.com/', true),
  ('nj07-bennett', 'no_corp_pac', 2, 'Campaign pledges no corporate PAC money. FEC: 6.4% of receipts from other political committees (includes ActBlue conduit).', 'https://api.open.fec.gov', true),
  ('ny07-valdez', 'gaza', 4, 'Issues page: "Push to end all weapons sales and military aid to Israel and fight for Palestinian freedom"; called for a ceasefire early and describes Gaza as genocide. Total arms and aid cutoff; attacked her primary opponent for AIPAC donor money.', 'https://clairevaldezforcongress.com/issues', false),
  ('ny07-valdez', 'gnd', 4, 'Issues page: rapid transition to an affordable, clean and reliable energy system, freeze electricity rates, publicly accountable renewable power for Puerto Rico, and support for the Sanders-AOC AI Data Center Moratorium Act. City & State lists her as a Green New Deal advocate. Public power and rapid transition; the platform summary does not say fossil fuel phaseout in those words.', 'https://clairevaldezforcongress.com/issues', true),
  ('ny07-valdez', 'housing', 4, 'Issues page: "Universal rent control; a full supply of homes through public investment; the right to a safe home; real tenant power and landlord accountability." Social housing and rent stabilization by name.', 'https://clairevaldezforcongress.com/issues', false),
  ('ny07-valdez', 'immigration', 4, 'Issues page: "In Congress, Claire Valdez will fight to dismantle and abolish ICE," and push reform that legalizes the status of millions. Abolish ICE plus pathway for all.', 'https://clairevaldezforcongress.com/issues', false),
  ('ny07-valdez', 'labor', 4, 'Issues page: "Strengthen and pass the PRO Act, establish active federal support for union organizing, and end at-will employment," plus a guaranteed job with a living wage and a 32-hour week at no loss of pay. Former UAW Local 2110 bargaining committee member. PRO Act plus structural labor reform.', 'https://clairevaldezforcongress.com/issues', false),
  ('ny07-valdez', 'm4a', 4, 'Campaign site: "Claire will sponsor Medicare for All on Day One"; platform includes full coverage for gender-affirming care, contraception and PrEP. Named directly.', 'https://clairevaldezforcongress.com/issues', false),
  ('ny07-valdez', 'no_corp_pac', 4, 'Media page: the only candidate in the race who has taken no money from the real estate lobby, landlords or developers; DSA-backed small-dollar campaign. Refuses corporate and industry money; explicit super PAC disavowal not found.', 'https://clairevaldezforcongress.com/media', true),
