  ('ny10-goldman', 'm4a', 4, 'Original cosponsor of H.R.3069, the Medicare for All Act (2025-04-29).', 'https://www.congress.gov/bill/119th-congress/house-bill/3069/cosponsors', false),
  ('ny10-goldman', 'no_corp_pac', 2, 'No corporate PAC pledge but self-funds from inherited wealth and benefited from outside money.', null, true),
  ('ny10-lander', 'gaza', 4, 'The Nation op-ed in his own name, February 2026: "I am announcing my support for HR 3565, the Block the Bombs Act." At the June debate said he would also support the Ceasefire Compliance Act and would not vote for additional military aid while Israel violates international law; calls it genocide; says he will not do AIPAC''s bidding. Raised from 3 to 4: campaigns on blocking offensive arms transfers and refuses AIPAC.', 'https://www.thenation.com/article/politics/brad-lander-block-the-bombs-act-gaza/', false),
  ('ny10-lander', 'gnd', 4, 'Jim Owles questionnaire: supports the Green New Deal; led the divestment of New York City pension funds from fossil fuels as comptroller; MoveOn: will advocate for a Green New Deal to reach net-zero. Raised from 3 to 4: Green New Deal by name plus a fossil fuel divestment record.', 'https://jimowles.org/news/candidate-answers-to-joldc-brad-lander-for-us-congress-ny-10-2026', false),
  ('ny10-lander', 'housing', 4, 'Founded his career leading the Fifth Avenue Committee, an affordable housing organization; advanced tenant eviction protections as a council member and comptroller; cross-endorsed Mamdani on rent freeze and social housing. Social housing and rent stabilization record.', 'https://www.thenation.com/article/politics/our-endorsement-brad-lander-for-congress/', true),
  ('ny10-lander', 'immigration', 4, 'MoveOn: supports a path to citizenship and expanded health coverage for undocumented neighbors; arrested at immigration court in June 2025 escorting a defendant from ICE agents. Pathway plus direct action against ICE enforcement.', 'https://front.moveon.org/endorsements/candidates/brad-lander-ny10/', false),
  ('ny10-lander', 'labor', 3, 'The Nation: passed paid sick leave over Bloomberg''s veto, stable scheduling, living wage and wage theft protections for contingent workers as a council member. Strong labor record; PRO Act not named in retrieved material.', 'https://www.thenation.com/article/politics/our-endorsement-brad-lander-for-congress/', true),
  ('ny10-lander', 'm4a', 4, 'Jim Owles questionnaire, his own words: "It did not take a primary challenge for me to support Medicare for All, the Green New Deal, and a wealth tax." MoveOn: strong supporter of Medicare for All. Raised from 3 to 4: named directly.', 'https://jimowles.org/news/candidate-answers-to-joldc-brad-lander-for-us-congress-ny-10-2026', false),
  ('ny10-lander', 'no_corp_pac', 3, 'Jim Owles questionnaire: contrasts himself with Goldman on stock trading and AIPAC money; campaign refuses corporate PAC money. Pledge on record; $574K in outside spending supported him.', 'https://jimowles.org/news/candidate-answers-to-joldc-brad-lander-for-us-congress-ny-10-2026', true),
  ('ny12-lasher', 'm4a', 4, 'Abundance NY questionnaire, his own words: "Pass Medicare for All because health care should be a right"; platform page supports Medicare for All or a similar universal plan. Raised from 2 to 4: named directly, with a hedge noted.', 'https://voterguide.abundanceny.org/questionnaires/micah-lasher-questionnaire', false),
  ('ny12-lasher', 'no_corp_pac', 1, 'Accepts PAC money; $22.8M in outside spending supported him. FEC: 0.7% of receipts from other political committees (includes ActBlue conduit).', 'https://api.open.fec.gov', true),
  ('ny12-bores', 'antitrust', 3, 'RAISE Act on frontier AI drew a super PAC funded by AI industry money against him.', null, true),
