  ('nc01-davis', 'gaza', 0, 'Cosponsors H.R.1229, the United States-Israel Defense Partnership Act, H.R.7540, H.R.7178 and H.R.2510 on Israel defense cooperation, with no ceasefire, conditioning or humanitarian measure. Arms-transfer clause of level 0.', 'https://www.congress.gov/member/don-davis/D000230', true),
  ('nc01-davis', 'immigration', 1, 'Voted for the Laken Riley Act in January 2025; cosponsors the American Dream and Promise Act. Enforcement-first with a Dreamer measure.', 'https://clerk.house.gov/Votes/202523', false),
  ('nc01-davis', 'm4a', 1, 'Cosponsors rural hospital and Medicare Advantage bills; no public option or single-payer position. Incremental only.', 'https://www.congress.gov/member/don-davis/D000230', true),
  ('nc01-davis', 'no_corp_pac', 1, 'Accepts corporate PAC money; AIPAC-aligned money supported him. No pledge.', 'https://www.congress.gov/member/don-davis/D000230', true),
  ('oh09-kaptur', 'antitrust', 3, 'Longtime Wall Street critic who has introduced Glass-Steagall restoration legislation in multiple Congresses. Financial structural reform; no stock ban or Big Tech breakup cosponsorship in the 119th.', 'https://www.congress.gov/member/marcy-kaptur/K000009', true),
  ('oh09-kaptur', 'labor', 4, 'Named in the introduced text of H.R.20 (PRO Act of 2025) as an original cosponsor.', 'https://www.govtrack.us/congress/bills/119/hr20/text', false),
  ('oh09-kaptur', 'm4a', 2, 'Longtime backer of a public option and Medicare buy-in; not single payer.', 'https://www.congress.gov/member/marcy-kaptur/K000009', true),
  ('oh09-kaptur', 'no_corp_pac', 1, 'Accepts corporate PAC money; no pledge. $4.6M in outside spending supported her.', 'https://www.congress.gov/member/marcy-kaptur/K000009', true),
  ('oh13-sykes', 'abortion', 3, 'Cosponsors H.R.12, the Women''s Health Protection Act of 2025; campaigned for Ohio''s 2023 Issue 1. WHPA plus state codification; Hyde repeal not found.', 'https://www.congress.gov/member/emilia-sykes/S001222', false),
  ('oh13-sykes', 'm4a', 2, 'Supports a public option and lowering drug costs; not single payer.', 'https://www.congress.gov/member/emilia-sykes/S001222', true),
  ('oh13-sykes', 'no_corp_pac', 2, 'Does not accept corporate PAC money per her campaign; $6.5M in outside spending supported her. Pledge alongside super PAC support.', 'https://www.emiliasykes.com/', true),
  ('pa01-harvie', 'm4a', 2, 'BallotReady: protect Medicare and Medicaid, expand affordable coverage, reinstate ACA credits; public option framing, not single payer.', 'https://www.ballotready.org/people/robert-harvie', true),
