  ('tx18-menefee', 'gnd', 3, 'As Harris County attorney sued petrochemical polluters including after the 2019 ITC fire and the 2023 Shell Deer Park fire; cosponsors H.R.8397 on climate and maternal health. Polluter accountability record; no fossil phaseout by name.', 'https://www.congress.gov/member/christian-menefee/M001245', true),
  ('tx18-menefee', 'justice', 3, 'Cosponsor of H.R.5361, the George Floyd Justice in Policing Act of 2025 as of 2026-03-24.', 'https://www.congress.gov/bill/119th-congress/house-bill/5361/cosponsors', false),
  ('tx18-menefee', 'm4a', 4, 'Cosponsor of H.R.3069, the Medicare for All Act as of 2026-04-21.', 'https://www.congress.gov/bill/119th-congress/house-bill/3069/cosponsors', false),
  ('tx18-menefee', 'no_corp_pac', 3, 'Does not accept corporate PAC money; Fairshake''s Protect Progress spent $12.9M supporting him without his solicitation. Pledge; the crypto super PAC support is recorded as a counter-signal.', 'https://www.menefeeforcongress.com/', true),
  ('tx18-green', 'democracy', 4, 'Filed Trump impeachment articles in 2017, 2019, and 2025; removed from the House floor for protesting in 2025.', null, true),
  ('tx18-green', 'gaza', 3, 'Supported ceasefire; voted to block some arms sales.', null, true),
