  ('sen-il-kelly', 'justice', 3, 'Original cosponsor of H.R.5361, the George Floyd Justice in Policing Act of 2025 (2025-09-15).', 'https://www.congress.gov/bill/119th-congress/house-bill/5361/cosponsors', false),
